import React, { useEffect, useState } from 'react';
import { useRouter, Link } from '@/router';
import { getProductBySlug, type Product } from '@/lib/services/store-data';
import { ProductDetailView } from '@/components/storefront/ProductDetailView';
import { ArrowLeft } from 'lucide-react';
import { useTranslation } from '@/i18n';

export function ProductView() {
  const { params } = useRouter();
  const { language } = useTranslation();
  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);

  const slug = params.slug;

  useEffect(() => {
    if (!slug) return;
    getProductBySlug(slug).then((p) => {
      setProduct(p);
      setLoading(false);
    });
  }, [slug]);

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 text-center text-slate-500">
        Loading product details...
      </div>
    );
  }

  if (!product) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 text-center space-y-4">
        <h2 className="text-xl font-bold text-slate-800">Product not found</h2>
        <p className="text-xs text-slate-500">The diaper product you are looking for may be unavailable or out of stock.</p>
        <Link to="/shop" className="btn-primary">
          Back to Diaper Catalog
        </Link>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-6">
      <Link
        to="/shop"
        className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-sky-600 transition-colors"
      >
        <ArrowLeft className="w-3.5 h-3.5" />
        <span>{language === 'bn' ? 'ক্যাটালগে ফিরে যান' : 'Back to Catalog'}</span>
      </Link>

      <ProductDetailView product={product} />
    </div>
  );
}
