import React, { useEffect, useState } from 'react';
import {
  Truck,
  Search,
  Package,
  CheckCircle2,
  Clock,
  MapPin,
  Phone,
  ShieldCheck,
  AlertCircle,
  ExternalLink,
} from 'lucide-react';
import { getOrderByToken, getOrderByNumberAndPhone, type OrderRecord } from '@/lib/services/store-data';
import { ORDER_STATUS_LABELS, formatDhakaDate } from '@/lib/constants';
import { useRouter, Link } from '@/router';
import { useTranslation } from '@/i18n';

const TIMELINE_STEPS = [
  { key: 'pending', label: 'Order Placed', labelBn: 'অর্ডার গ্রহণ' },
  { key: 'confirmed', label: 'Confirmed', labelBn: 'নিশ্চিত করা হয়েছে' },
  { key: 'processing', label: 'Packaging', labelBn: 'প্যাকেজিং চলছে' },
  { key: 'shipped', label: 'Dispatched', labelBn: 'কুরিয়ারে হস্তান্তর' },
  { key: 'out_for_delivery', label: 'Out for Delivery', labelBn: 'ডেলিভারির পথে' },
  { key: 'delivered', label: 'Delivered', labelBn: 'ডেলিভারি সম্পন্ন' },
];

export function TrackOrderView() {
  const { searchParams } = useRouter();
  const { formatPrice, t, language } = useTranslation();

  const [queryToken, setQueryToken] = useState(searchParams.get('token') || '');
  const [orderNumber, setOrderNumber] = useState(searchParams.get('order') || '');
  const [phone, setPhone] = useState('');
  const [order, setOrder] = useState<OrderRecord | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Auto-search if token query param present
  useEffect(() => {
    const token = searchParams.get('token');
    if (token) {
      setQueryToken(token);
      lookupByToken(token);
    }
  }, [searchParams]);

  const lookupByToken = async (tokenStr: string) => {
    if (!tokenStr.trim()) return;
    setLoading(true);
    setError('');
    try {
      const res = await getOrderByToken(tokenStr.trim());
      if (res) {
        setOrder(res);
      } else {
        setError(language === 'bn' ? 'টোকেনটির বিপরীতে কোনো অর্ডার পাওয়া যায়নি।' : 'No order found with this tracking token.');
        setOrder(null);
      }
    } catch {
      setError('An error occurred during order lookup.');
    } finally {
      setLoading(false);
    }
  };

  const handleSearchSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (queryToken.trim()) {
      lookupByToken(queryToken);
      return;
    }

    if (orderNumber.trim() && phone.trim()) {
      setLoading(true);
      try {
        const res = await getOrderByNumberAndPhone(orderNumber.trim(), phone.trim());
        if (res) {
          setOrder(res);
        } else {
          setError(language === 'bn' ? 'অর্ডার নম্বর বা ফোন নম্বর মিলছে না।' : 'Order number and phone number combination not found.');
          setOrder(null);
        }
      } catch {
        setError('An error occurred during order lookup.');
      } finally {
        setLoading(false);
      }
    } else {
      setError(language === 'bn' ? 'অনুগ্রহ করে ট্র্যাকিং টোকেন অথবা অর্ডার নম্বর ও ফোন নম্বর দিন।' : 'Please enter either a tracking token OR both order number and phone number.');
    }
  };

  const getStepStatus = (stepKey: string, currentStatus: string) => {
    const orderIndex = TIMELINE_STEPS.findIndex((s) => s.key === currentStatus);
    const stepIndex = TIMELINE_STEPS.findIndex((s) => s.key === stepKey);

    if (currentStatus === 'cancelled') return 'cancelled';
    if (stepIndex < orderIndex) return 'completed';
    if (stepIndex === orderIndex) return 'current';
    return 'upcoming';
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 space-y-8">
      {/* Header */}
      <div className="text-center space-y-2 max-w-xl mx-auto">
        <div className="w-12 h-12 rounded-2xl bg-sky-100 text-sky-600 flex items-center justify-center mx-auto">
          <Truck className="w-6 h-6" />
        </div>
        <h1 className="text-2xl sm:text-3xl font-extrabold text-slate-900 tracking-tight">
          {t.tracking.title}
        </h1>
        <p className="text-xs text-slate-500">
          {t.tracking.subtitle}
        </p>
      </div>

      {/* Search Form Card */}
      <div className="bg-white rounded-3xl border border-slate-200/80 p-6 sm:p-8 shadow-xs space-y-6">
        <form onSubmit={handleSearchSubmit} className="space-y-4">
          <div className="space-y-2">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-700">
              {language === 'bn' ? 'পদ্ধতি ১: গোপন ট্র্যাকিং টোকেন (৪৮ অক্ষর)' : 'Method 1: 48-Character Tracking Token'}
            </label>
            <div className="relative">
              <input
                type="text"
                value={queryToken}
                onChange={(e) => setQueryToken(e.target.value)}
                placeholder={t.tracking.searchPlaceholder}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 pl-4 pr-10 text-xs font-mono outline-hidden focus:bg-white focus:border-sky-500"
              />
              <Search className="w-4 h-4 text-slate-400 absolute right-3.5 top-3.5" />
            </div>
          </div>

          <div className="relative flex py-2 items-center">
            <div className="flex-grow border-t border-slate-200"></div>
            <span className="flex-shrink mx-4 text-slate-400 text-xs uppercase font-bold tracking-wider">
              {language === 'bn' ? 'অথবা' : 'OR'}
            </span>
            <div className="flex-grow border-t border-slate-200"></div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-1">
                {language === 'bn' ? 'পদ্ধতি ২: অর্ডার নম্বর' : 'Method 2: Order Number'}
              </label>
              <input
                type="text"
                value={orderNumber}
                onChange={(e) => setOrderNumber(e.target.value)}
                placeholder="e.g. LT-00001"
                className="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-4 text-xs font-mono outline-hidden focus:bg-white focus:border-sky-500"
              />
            </div>
            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-1">
                {t.checkout.phone}
              </label>
              <input
                type="tel"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder="01797753722"
                className="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-4 text-xs font-mono outline-hidden focus:bg-white focus:border-sky-500"
              />
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3.5 bg-sky-600 hover:bg-sky-700 text-white rounded-xl text-xs font-bold transition-all shadow-md shadow-sky-600/20 flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
          >
            <Search className="w-4 h-4" />
            <span>{loading ? 'Searching...' : t.tracking.trackBtn}</span>
          </button>
        </form>

        {error && (
          <div className="p-4 rounded-xl bg-rose-50 border border-rose-200 text-rose-800 text-xs font-semibold flex items-center gap-2">
            <AlertCircle className="w-4 h-4 text-rose-600 shrink-0" />
            <span>{error}</span>
          </div>
        )}
      </div>

      {/* Order Status Timeline & Inspection Card */}
      {order && (
        <div className="bg-white rounded-3xl border border-slate-200/80 p-6 sm:p-8 space-y-8 shadow-xs animate-fade-in">
          {/* Order Header Summary */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-100 pb-6">
            <div>
              <div className="flex items-center gap-3">
                <h2 className="text-xl font-extrabold text-slate-900 font-mono">
                  {order.orderNumber}
                </h2>
                <span
                  className={`text-xs px-3 py-1 rounded-full font-bold border ${
                    ORDER_STATUS_LABELS[order.orderStatus]?.color || 'bg-slate-100 text-slate-800'
                  }`}
                >
                  {ORDER_STATUS_LABELS[order.orderStatus]?.label || order.orderStatus}
                </span>
              </div>
              <p className="text-xs text-slate-400 mt-1">
                Placed on {formatDhakaDate(order.createdAt)} • Cash On Delivery
              </p>
            </div>

            <div className="sm:text-right">
              <span className="text-xs text-slate-400">{t.cart.total}</span>
              <p className="text-2xl font-extrabold text-slate-900">
                {formatPrice(order.total)}
              </p>
            </div>
          </div>

          {/* Timeline Visualizer */}
          <div className="space-y-4">
            <h3 className="text-xs font-bold uppercase tracking-wider text-slate-700">
              {t.tracking.timelineTitle}
            </h3>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-3">
              {TIMELINE_STEPS.map((step, idx) => {
                const status = getStepStatus(step.key, order.orderStatus);
                return (
                  <div
                    key={step.key}
                    className={`p-3.5 rounded-2xl border text-center space-y-1.5 transition-all ${
                      status === 'completed'
                        ? 'bg-emerald-50 border-emerald-200 text-emerald-900'
                        : status === 'current'
                        ? 'bg-sky-50 border-sky-400 text-sky-950 ring-2 ring-sky-200'
                        : 'bg-slate-50 border-slate-200 text-slate-400 opacity-60'
                    }`}
                  >
                    <div className="w-6 h-6 rounded-full flex items-center justify-center mx-auto text-[11px] font-bold">
                      {status === 'completed' ? (
                        <CheckCircle2 className="w-5 h-5 text-emerald-600" />
                      ) : (
                        <span>{idx + 1}</span>
                      )}
                    </div>
                    <p className="text-[11px] font-bold leading-tight">
                      {language === 'bn' ? step.labelBn : step.label}
                    </p>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Courier Dispatch Consignment Information */}
          {order.courierPartner && (
            <div className="p-4 rounded-2xl bg-indigo-50 border border-indigo-100 text-xs text-indigo-900 flex items-center justify-between">
              <div>
                <span className="font-semibold">{t.tracking.courierPartner} {order.courierPartner}</span>
                {order.courierConsignmentId && (
                  <p className="font-mono text-indigo-700 mt-0.5">
                    {t.tracking.consignmentId} {order.courierConsignmentId}
                  </p>
                )}
              </div>
              {order.courierTrackingUrl && (
                <a
                  href={order.courierTrackingUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="px-3 py-1.5 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition-colors flex items-center gap-1 shrink-0"
                >
                  <span>Track Courier</span>
                  <ExternalLink className="w-3 h-3" />
                </a>
              )}
            </div>
          )}

          {/* Details Grid: Delivery Address & Item Snapshots */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-slate-100 text-xs">
            <div className="space-y-2">
              <h4 className="font-bold uppercase tracking-wider text-slate-500">
                {t.checkout.deliveryAddress}
              </h4>
              <p className="font-semibold text-slate-800 text-sm">{order.customerName}</p>
              <p className="text-slate-600">{order.customerPhone}</p>
              <p className="text-slate-600 whitespace-pre-line">{order.deliveryAddress}</p>
              <p className="text-slate-500 font-medium">Zone: {order.deliveryZoneName}</p>
            </div>

            <div className="space-y-2">
              <h4 className="font-bold uppercase tracking-wider text-slate-500">
                {language === 'bn' ? 'অর্ডারকৃত ডায়াপার আইটেম' : 'Ordered Diaper Items'}
              </h4>
              <div className="divide-y divide-slate-100">
                {order.items.map((i) => (
                  <div key={i.id} className="py-2 flex justify-between">
                    <div>
                      <p className="font-bold text-slate-800">{i.productName}</p>
                      <p className="text-[11px] text-slate-500">
                        Size {i.size} ({i.packCount} pcs) × {i.quantity}
                      </p>
                    </div>
                    <span className="font-bold text-slate-900">{formatPrice(i.subtotal)}</span>
                  </div>
                ))}
                <div className="pt-2 flex justify-between font-semibold text-slate-600">
                  <span>{t.cart.deliveryCharge}</span>
                  <span>{formatPrice(order.deliveryCharge)}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
